const query = 'query GetNewTitles($country: Country!, $language: Language!, $first: Int!, $date: Date!, $filter: TitleFilter, $pageType: NewPageType!, $priceDrops: Boolean!, $platform: Platform!) { newTitles(country: $country, date: $date, first: $first, filter: $filter, pageType: $pageType, priceDrops: $priceDrops) { edges { newOffer(platform: $platform) { monetizationType package { clearName } } node { ... on MovieOrSeason { id objectType content(country: $country, language: $language) { title shortDescription posterUrl fullPath originalReleaseYear } } ... on Season { show { id content(country: $country, language: $language) { title posterUrl fullPath } } } } } } }';
const img = p => p ? 'https://images.justwatch.com' + p.replace('{profile}', 's276').replace('{format}', 'jpg') : '';
const out = { movies: [], series: [] };
const seen = new Set();
for (let i = 0; i < 7; i++) {
  const d = new Date(Date.now() - i * 86400000).toISOString().slice(0, 10);
  let res;
  try {
    res = await this.helpers.httpRequest({ method: 'POST', url: 'https://apis.justwatch.com/graphql', json: true, body: { operationName: 'GetNewTitles', query, variables: { country: 'FR', language: 'fr', first: 60, date: d, filter: { packages: ['nfx', 'cpd', 'prv', 'dnp', 'atp', 'mxx'] }, pageType: 'NEW', priceDrops: false, platform: 'WEB' } } });
  } catch (e) { continue; }
  for (const e of res?.data?.newTitles?.edges || []) {
    if (e.newOffer?.monetizationType !== 'FLATRATE') continue;
    const n = e.node; if (!n?.content) continue;
    const isSeries = n.objectType === 'SHOW_SEASON';
    const id = isSeries ? n.show?.id : n.id;
    if (!id || seen.has(id)) continue;
    seen.add(id);
    const item = {
      id,
      title: isSeries ? (n.show?.content?.title || '') : n.content.title,
      season: isSeries ? n.content.title : '',
      year: n.content.originalReleaseYear || null,
      poster: img(n.content.posterUrl || n.show?.content?.posterUrl),
      synopsis: n.content.shortDescription || '',
      platform: e.newOffer?.package?.clearName || '',
      date: d,
      url: n.content.fullPath ? 'https://www.justwatch.com' + n.content.fullPath : ''
    };
    (isSeries ? out.series : out.movies).push(item);
  }
}
return [{ json: out }];
